const CustomLink = ({ href, children }) => {
  // Check if we are on GitHub and if the link already has the prefix
  const isGitHub = window.location.hostname.includes("github.io");
  const repoName = "/CALCULUS_QUICK_NOTES_WEB";
  
  // Create the final path: if on GitHub, prepend repoName (if it's not already there)
  const finalHref = isGitHub && !href.startsWith(repoName) 
    ? `${repoName}${href}` 
    : href;

  return (
    <Link
      href={finalHref} // Use the fixed path here
      underline="none"
      color={sunsetPinkHeavy}
      sx={{
        fontWeight: "fontWeightHeavy",
      }}
    >
      {children}
    </Link>
  );
};

export default CustomLink;
